//! Exact `model.Job.Encode(true)` vectors for the source-owned name extractor.

use tidb_meta::transaction::extract_schema_and_table_name_from_job;

fn decode_hex(value: &str) -> Vec<u8> {
    assert_eq!(value.len() % 2, 0, "hex input must have an even length");
    value
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            let high = (pair[0] as char).to_digit(16).expect("hex high nibble");
            let low = (pair[1] as char).to_digit(16).expect("hex low nibble");
            ((high << 4) | low) as u8
        })
        .collect()
}

#[test]
fn actual_go_job_encoding_keeps_name_extraction_on_the_top_level_fields() {
    // Captured from model.Job.Encode(true) in pkg/meta/meta_test.go's exact ten cases.
    // Every Job also contains misleading schema/table fragments in Error, Warning,
    // and Query so a field-order or substring-search regression returns the wrong name.
    let vectors = [
        ("", "736368656d615f6e616d65", ""),
        ("7461626c655f6e616d65", "", ""),
        ("2271756f74615f736368656d615f6e616d6522", "2271756f74615f7461626c655f6e616d6522", ""),
        ("2273696e676c655f71756f7461", "2222747269706c655f71756f746122", ""),
        ("22736368656d615f6e616d6522", "227461626c655f6e616d6522", ""),
        ("5c", "5c5c", ""),
        ("e4b8ade6968731", "e4b8ade6968732", ""),
        ("f09f988b", "f09f98ad", ""),
        ("636f6d6d612c31", "646f742e33", ""),
        ("22636f6d62696e653a5c5c5c222ce4bda0e5a5bd5c5c", "22736368656d615f6e616d653a31efb88fe283a3222c227461626c655f6e616d653a32efb88fe283a322", ""),
    ];

    assert_eq!(vectors.len(), 10);
    for (schema_hex, table_hex, job_hex) in vectors {
        let encoded = decode_hex(job_hex);
        let (schema, table) =
            extract_schema_and_table_name_from_job(&encoded).expect("Go Job vector decodes");
        assert_eq!(schema.as_bytes(), decode_hex(schema_hex));
        assert_eq!(table.as_bytes(), decode_hex(table_hex));
    }
}
